import random
import struct
import itertools
from typing import List

# This generator targets arbitrary bytes that will be used by fuzzer stubs
# as JS strings or binary buffers. We focus on producing valid, interesting
# content that exercises different code paths: ASCII, UTF-8, null bytes,
# repeated patterns, JSON snippets, URL query strings, and mixed binary.

_MAX_SIZE = 1024  # stubs cap at 1024 in several places; stay within limits


def _rand(r: random.Random, a: int, b: int) -> int:
    return r.randint(a, b)


def _choice(r: random.Random, seq):
    return seq[r.randrange(len(seq))]


def _weighted_choice(r: random.Random, choices):
    # choices: list of (weight, value)
    total = sum(w for w, _ in choices)
    pick = r.random() * total
    acc = 0.0
    for w, v in choices:
        acc += w
        if pick <= acc:
            return v
    return choices[-1][1]


def _ascii_text(r: random.Random, min_len=1, max_len=256) -> bytes:
    l = _rand(r, min_len, max_len)
    # Printable ASCII plus some whitespace and punctuation
    alphabet = (
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789"
        " _-.:,/\\\n\t=+*&%$#@!?\'\"()[]{}<>"
    )
    s = ''.join(_choice(r, alphabet) for _ in range(l))
    # Occasionally ensure non-empty alnum start to exercise parsers
    return s.encode('utf-8')


def _utf8_text(r: random.Random, min_len=1, max_len=256) -> bytes:
    # Build a UTF-8 string with a mix of ranges
    l = _rand(r, min_len, max_len)
    out = bytearray()
    # Weighted ranges: ASCII, Latin-1 supplement, BMP, emoji
    for _ in range(l):
        cp = _weighted_choice(r, [
            (5, _rand(r, 0x20, 0x7e)),        # ASCII printable
            (2, _rand(r, 0x00a0, 0x024f)),    # Latin-1/Extended
            (2, _rand(r, 0x0400, 0x052f)),    # Cyrillic
            (2, _rand(r, 0x0370, 0x03ff)),    # Greek
            (1, _rand(r, 0x4e00, 0x9fff)),    # CJK
            (1, _rand(r, 0x1f300, 0x1f6ff)),  # Emoji range
        ])
        # Avoid surrogate range
        if 0xD800 <= cp <= 0xDFFF:
            cp = 0xFFFD
        out.extend(chr(cp).encode('utf-8'))
    return bytes(out)


def _with_nulls(data: bytes, r: random.Random) -> bytes:
    if not data:
        return b"\x00"
    # Insert a few null bytes at random positions
    count = _rand(r, 1, max(1, len(data)//16))
    b = bytearray(data)
    for _ in range(count):
        pos = _rand(r, 0, len(b))
        b[pos:pos] = b"\x00"
    return bytes(b)


def _repeated_pattern(r: random.Random, max_len=512) -> bytes:
    pats = [
        b"A", b"AB", b"\x00\xff", b"\r\n", b"0123456789", b"deadbeef",
        b"\x01\x02\x03\x04", b"\xf0\x9f\x98\x80"  # 😀 utf-8 bytes
    ]
    pat = _choice(r, pats)
    reps = _rand(r, 1, max(1, max_len // max(1, len(pat))))
    data = (pat * reps)[:max_len]
    return data


def _json_sample(r: random.Random) -> bytes:
    # Valid JSONs to exercise JSON.parse/stringify
    samples = [
        b"null", b"0", b"[]", b"{}", b"\"x\"", b"true", b"false",
