        for ch in s:
            if ch in safe:
                out.append(ch)
            elif ch == ' ':
                out.append(_choice(r, ['+', '%20']))
            else:
                out.append('%%%02X' % ord(ch))
        return ''.join(out)
    keys = ["a","b","c","d","token","q","x","y","z","name","value"]
    vals = ["1","2","3","hello","世界","😀","","true","false","null","longvalue"]
    parts = []
    for i in range(pairs):
        k = enc(_choice(r, keys))
        v = enc(_choice(r, vals))
        parts.append(f"{k}={v}")
    # Occasionally include key with no value or repeated keys
    if r.random() < 0.3:
        parts.append(enc(_choice(r, keys)))
    return '&'.join(parts).encode('utf-8')


def _binary_blob(r: random.Random, min_len=1, max_len=1024) -> bytes:
    l = _rand(r, min_len, max_len)
    b = bytearray(l)
    # Mix ranges: 0x00, 0xff, ASCII, random bytes
    for i in range(l):
        t = _weighted_choice(r, [(2, 0), (2, 255), (4, 1), (4, 2)])
        if t == 0:
            b[i] = 0
        elif t == 1:
            b[i] = _rand(r, 0x20, 0x7e)
        elif t == 2:
            b[i] = _rand(r, 0, 255)
        else:
            b[i] = 255
    return bytes(b)


def _truncate(data: bytes, max_len: int) -> bytes:
    if len(data) <= max_len:
        return data
    return data[:max_len]


def _compose(r: random.Random) -> bytes:
    # Choose a theme based on weighted selection to increase coverage for
    # string operations, buffer operations, comparisons, JSON, and query parsing.
    theme = _weighted_choice(r, [
        (3, 'ascii'),
        (3, 'utf8'),
        (2, 'ascii_nulls'),
        (2, 'pattern'),
        (2, 'json'),
        (2, 'query'),
        (3, 'binary'),
    ])

    if theme == 'ascii':
        data = _ascii_text(r, 1, _rand(r, 8, 256))
    elif theme == 'utf8':
        data = _utf8_text(r, 1, _rand(r, 8, 256))
    elif theme == 'ascii_nulls':
        data = _with_nulls(_ascii_text(r, 1, _rand(r, 8, 128)), r)
    elif theme == 'pattern':
        data = _repeated_pattern(r, max_len=_rand(r, 16, 512))
    elif theme == 'json':
        # Sometimes mix valid JSON with trailing/leading spaces or newlines
        base = _json_sample(r)
        if r.random() < 0.3:
            base = b"\n" + base + b"\n"
        data = base
    elif theme == 'query':
        data = _url_query(r)
    else:  # binary
        data = _binary_blob(r, 1, _rand(r, 16, 1024))

    # Occasionally concatenate small segments to create longer strings for compare/dump
    if r.random() < 0.25:
        segs: List[bytes] = [data]
        for _ in range(_rand(r, 1, 3)):
            seg_kind = _choice(r, ['ascii','utf8','bin'])
            if seg_kind == 'ascii':
                segs.append(_ascii_text(r, 1, _rand(r, 4, 64)))
            elif seg_kind == 'utf8':
                segs.append(_utf8_text(r, 1, _rand(r, 4, 64)))
            else:
                segs.append(_binary_blob(r, 1, _rand(r, 4, 64)))
        data = b''.join(segs)

    # Ensure non-empty (stubs bail on empty strings)
    if not data:
        data = b"x"

    return _truncate(data, _MAX_SIZE)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    return _compose(r)
